// ❌ The double problem — floating-point imprecision
double price = 0.1 + 0.2;
System.out.println(price); // 0.30000000000000004 ← WRONG!

double total = 1.005 * 100;
System.out.println(total); // 100.49999999999999 ← rounds to 100.49, not 100.50!

// ❌ Even when reading from DB as DECIMAL, intermediate math corrupts it:
double balance = 100.10; // Read from DB correctly
double fee = 0.10;
double result = balance - fee;
System.out.println(result); // 99.99999999999999 ← incorrect!

// ✅ Correct: Use BigDecimal from the start
BigDecimal price = new BigDecimal("0.1"); // Always use String constructor!
BigDecimal tax = new BigDecimal("0.2");
BigDecimal total = price.add(tax);
System.out.println(total); // 0.3 ← exact!

// ❌ Common mistake: BigDecimal from double is still imprecise!
BigDecimal wrong = new BigDecimal(0.1); // 0.1000000000000000055511...
BigDecimal right = new BigDecimal("0.1"); // exactly 0.1

// ✅ Rounding for financial display (e.g., banking)
BigDecimal amount = new BigDecimal("100.005");
BigDecimal rounded = amount.setScale(2, RoundingMode.HALF_UP);
System.out.println(rounded); // 100.01

// ✅ In Spring Boot with JPA — use BigDecimal for money fields
@Entity
public class Account {
    @Column(precision = 19, scale = 4) // Maps to DECIMAL(19,4)
    private BigDecimal balance;
}

// ✅ Comparison: NEVER use == or .equals() for scale mismatch
BigDecimal a = new BigDecimal("1.0");
BigDecimal b = new BigDecimal("1.00");
System.out.println(a.equals(b));      // false! (different scale)
System.out.println(a.compareTo(b));   // 0 ← correct for value equality
